function isRationalEqual(s, t) {
  const gcd = (x, y) => (y === 0 ? x : gcd(y, x % y));

  function toFraction(text) {
    const dot = text.indexOf('.');
    if (dot === -1) return [Number(text), 1];
    const open = text.indexOf('(');
    const integer = Number(text.slice(0, dot));
    const fixed = text.slice(dot + 1, open === -1 ? text.length : open);
    const shift = 10 ** fixed.length;
    let numerator = integer * shift + Number(fixed);
    let denominator = shift;
    if (open !== -1) {
      const cycle = text.slice(open + 1, -1);
      const nines = 10 ** cycle.length - 1;
      numerator = numerator * nines + Number(cycle);
      denominator = denominator * nines;
    }
    const divisor = gcd(numerator, denominator);
    return [numerator / divisor, denominator / divisor];
  }

  const first = toFraction(s);
  const second = toFraction(t);
  return first[0] === second[0] && first[1] === second[1];
}

