function isRationalEqual(s, t) {
  // Write 60 decimal places of each number as one big integer. Equal values differ by at most
  // one unit in the last place (0.999... against 1.000...); distinct values differ far more.
  const expand = (text) => {
    const [, whole, fixed = '', cycle = ''] = text.match(/^(\d+)(?:\.(\d*)(?:\((\d+)\))?)?$/);
    let digits = fixed;
    while (cycle && digits.length < 60) digits += cycle;
    return BigInt(whole + digits.slice(0, 60).padEnd(60, '0'));
  };
  const gap = expand(s) - expand(t);
  return gap >= -1n && gap <= 1n;
}

