function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const digits = (length) => Array.from({ length }, () => String(pick(10))).join('');
  const limit = size === 'large' ? 4 : 3;
  const randomForm = () => {
    const width = 1 + pick(limit);
    const I = width === 1 ? String(pick(10)) : String(1 + pick(9)) + digits(width - 1);
    const form = pick(3);
    if (form === 0) return { I, N: '', R: null, dot: false };
    const N = digits(pick(limit + 1));
    if (form === 1) return { I, N, R: null, dot: rand() < 0.5 || N !== '' };
    const roll = rand();
    const R = roll < 0.15 ? '9'.repeat(1 + pick(2)) : roll < 0.3 ? '0'.repeat(1 + pick(2)) : digits(1 + pick(limit));
    return { I, N, R, dot: true };
  };
  // Each step rewrites a number into another valid spelling of the same value (or returns null).
  const shiftDigits = (x, delta, R) => {
    const all = x.I + x.N;
    const moved = String(Number(all) + delta).padStart(all.length, '0');
    const cut = moved.length - x.N.length;
    const I = moved.slice(0, cut).replace(/^0+(?=\d)/, '');
    return I.length > 4 ? null : { I, N: moved.slice(cut), R, dot: true };
  };
  const steps = [
    (x) => (x.R && x.N.length < 4 ? { ...x, N: x.N + x.R[0], R: x.R.slice(1) + x.R[0] } : null),
    (x) => (x.R && x.N && x.N.at(-1) === x.R.at(-1) ? { ...x, N: x.N.slice(0, -1), R: x.R.at(-1) + x.R.slice(0, -1) } : null),
    (x) => (x.R && x.R.length * 2 <= 4 ? { ...x, R: x.R + x.R } : null),
    (x) => (x.R && x.R.length % 2 === 0 && x.R.slice(0, x.R.length / 2) === x.R.slice(x.R.length / 2) ? { ...x, R: x.R.slice(0, x.R.length / 2) } : null),
    (x) => (x.R && /^0+$/.test(x.R) ? { ...x, R: null } : null),
    (x) => (!x.R ? { ...x, R: '0'.repeat(1 + pick(2)), dot: true } : null),
    (x) => (!x.R && x.N.length < 4 ? { ...x, N: x.N + '0', dot: true } : null),
    (x) => (!x.R && x.N.endsWith('0') ? { ...x, N: x.N.slice(0, -1) } : null),
    (x) => (!x.R && !x.N ? { ...x, dot: !x.dot } : null),
    (x) => (!x.R && Number(x.I + x.N) > 0 ? shiftDigits(x, -1, '9') : null),
    (x) => (x.R && /^9+$/.test(x.R) ? shiftDigits(x, 1, null) : null),
  ];
  const walk = (x) => {
    for (let count = pick(7); count > 0; count--) {
      const options = steps.map(step => step(x)).filter(Boolean);
      if (options.length === 0) break;
      x = options[pick(options.length)];
    }
    return x;
  };
  const tweak = (x) => {
    const keys = ['I', 'N', 'R'].filter(key => x[key]);
    const key = keys[pick(keys.length)];
    const at = pick(x[key].length);
    let digit = String(pick(10));
    if (key === 'I' && at === 0 && x[key].length > 1 && digit === '0') digit = '1';
    return { ...x, [key]: x[key].slice(0, at) + digit + x[key].slice(at + 1) };
  };
  const write = (x) => x.I + (x.dot || x.N || x.R ? '.' + x.N : '') + (x.R ? '(' + x.R + ')' : '');
  const base = randomForm();
  const first = walk(base);
  let second = walk(base);
  const mode = rand();
  if (mode < 0.3) second = tweak(second);
  else if (mode < 0.42) second = randomForm();
  return rand() < 0.5 ? [write(first), write(second)] : [write(second), write(first)];
}
